mapper.select:
select fundId, finprodName, serialNo, interType, xmlStatus, checkStatus, valDate from (SELECT BASI.ACCT_SUBJECT_ID fundId, BASI.ACCT_SUBJECT_NAME finprodName, SIV.SERIALNO serialNo, '0' interType,
(case when SIV.XML_STATUS = null then 0 else SIV.XML_STATUS end) xmlStatus,
(case when SIV.CHECK_STATUS = null then 0 else SIV.CHECK_STATUS end) checkStatus, DATE_FORMAT(B.BALANCE_DATE, '%Y-%m-%d') valDate FROM (SELECT DISTINCT A.BOOKSET_ID, A.BALANCE_DATE FROM BOK_BALANCE A) B LEFT JOIN BOK_BOOKSET BB ON B.BOOKSET_ID = BB.BOOKSET_ID AND BB.ACCT_SUBJECT_TYPE = 'F16' LEFT JOIN BOK_ACCT_SUBJECT_INFO BASI ON BB.ACCT_SUBJECT_ID = BASI.ACCT_SUBJECT_ID AND BASI.ACCT_SUBJECT_TYPE = 'F16' LEFT JOIN SZT_INTERF_VALUATION SIV ON SIV.FINPROD_ID = BB.ACCT_SUBJECT_ID AND SIV.INTER_TYPE = '0' AND SIV.CDATE = DATE_FORMAT(B.BALANCE_DATE, '%Y-%m-%d')) where 1 = 1 and fundId = #{fundId,jdbcType=VARCHAR} and valDate = DATE_FORMAT(STR_TO_DATE(#{valDate,jdbcType=DATE},'%Y-%m-%d'),'%Y-%m-%d') and xmlStatus = #{xmlStatus,jdbcType=VARCHAR} and checkStatus = #{checkStatus,jdbcType=VARCHAR}
